(function(){
'use strict';var root=document.getElementById('schedule-editor'),mute=document.getElementById('quick-mute'),bell=document.getElementById('quick-bell'),status=document.getElementById('quick-status');
var volume=document.getElementById('router-volume'),volumeSave=document.getElementById('volume-save'),volumeStatus=document.getElementById('volume-status'),volumeDirty=false;
var state=null,busy=false,ringing=false,checking=false,epoch=0,lastCheck=0;
function draw(){if(window.schoolbellSessionBlocked){volume.disabled=true;volumeSave.disabled=true;mute.disabled=true;bell.disabled=true;mute.textContent="Без звука";status.textContent="Войдите для управления звуком. Состояние устройства после выхода не обновляется.";return;}volume.disabled=busy || !state;volumeSave.disabled=busy || !state || !volumeDirty;if(state && !volumeDirty){var gain=state.volume_db===undefined?0:state.volume_db;if(!Array.from(volume.options).some(function(o){return Number(o.value)===gain;})){var option=document.createElement('option');option.value=String(gain);option.textContent=gain+' дБ';volume.appendChild(option);}volume.value=String(gain);}mute.disabled=busy || !state;bell.disabled=busy || ringing || !state || state.muted || state.playing || state.hardware===false;mute.setAttribute('aria-pressed',String(!!(state && state.muted)));if(state && state.hardware===false)bell.title='Устройство не подключён к публичному демо';mute.textContent=state?(state.muted?'🔇 Без звука':'🔊 Без звука'):'Без звука · неизвестно';}
async function request(url,body){var abort=new AbortController(),timer=setTimeout(function(){abort.abort();},35000);try{var o={credentials:'same-origin',cache:'no-store',redirect:'error',signal:abort.signal};if(body){o.method='POST';o.body=new URLSearchParams(Object.assign({token:root.dataset.token},body));}var r=await fetch(url,o);if(!r.ok)throw Error(r.status===403 || r.status===401?'auth':'http');try{return await r.json();}catch(_){throw Error('response');}}finally{clearTimeout(timer);}}
async function refresh(){if(window.schoolbellSessionBlocked || busy || checking || document.hidden)return;checking=true;var started=epoch;try{var s=await request(root.dataset.controls);if(!s.ok)throw Error(s.code || 'state');if(started!==epoch)return;state=s;if(s.muted)status.textContent=s.playing?'Без звука включён. Ожидаем подтверждения остановки проигрывателя…':'Без звука включён. Звук устройства заблокирован.';else if(!ringing)status.textContent=s.playing?'Звонок выполняется. Без звука доступен.':'Звук устройства разрешён. Ручной звонок — один раз, без расписания.';}catch(e){if(started===epoch){state=null;var messages={auth:'Войдите в LuCI заново, чтобы управлять звуком.',response:'Ответ сервера не распознан. Обновите страницу или войдите в LuCI.',control_unreadable:'Не удалось прочитать настройки звука на устройстве. Повторяем проверку.',http:'Сервер вернул ошибку запроса состояния звука.'};status.textContent=messages[e.message] || 'Не получен ответ о состоянии звука. Повторяем проверку.';}}finally{checking=false;lastCheck=Date.now();draw();}}
volume.addEventListener('change',function(){volumeDirty=true;draw();});
volumeSave.addEventListener('click',async function(){if(busy || !state)return;epoch++;busy=true;draw();volumeStatus.textContent='Сохраняем громкость…';try{var s=await request(root.dataset.controls,{volume_db:volume.value});if(!s.ok)throw Error('volume');state=s;volumeDirty=false;volumeStatus.textContent='Сохранено: '+s.volume_db+' дБ. Применится к следующему звонку.';}catch(_){volumeStatus.textContent='Сохранение не подтверждено. Обновите страницу и проверьте громкость.';}finally{busy=false;draw();}});
mute.addEventListener('click',async function(){if(!state || busy)return;epoch++;busy=true;draw();status.textContent='Применяем Без звука…';try{var s=await request(root.dataset.controls,{muted:String(!state.muted)});if(!s.ok)throw Error('mute');state=s;}catch(_){state=null;status.textContent='Результат Без звука неизвестен. Не считайте звук отключённым до подтверждения.';}finally{busy=false;draw();await refresh();}});
bell.addEventListener('click',async function(){if(!state || state.muted || state.playing || ringing)return;ringing=true;draw();status.textContent='Ручной звонок на устройстве…';try{var r=await request(root.dataset.manual,{});status.textContent=r.ok?'Ручной звонок завершён.':r.state==='muted'?'Звонок остановлен или запрещён Без звука.':'Звонок не подтверждён: '+r.state;}catch(_){status.textContent='Ответ потерян: звонок мог начаться. Не повторяйте сразу.';}finally{ringing=false;draw();}});
window.addEventListener('schoolbell-session-lost',function(){epoch++;state=null;draw();});window.addEventListener('schoolbell-session-restored',refresh);
refresh();setInterval(function(){if(ringing || (state && state.playing) || Date.now()-lastCheck>=15000)refresh();},2000);document.addEventListener('visibilitychange',refresh);
}());
